\begin{remark}[Role of the scalar-curvature hypothesis]
\label{rem:chow-iii-pseudolocality-scalar-role}
\source{chow-et-al-ricci-flow-part-iii:page-0200}
\dcref{ch21:21.18}
\group{Logarithmic Sobolev contradiction}

